// Block (composition) — Panel: carrier identity belongs above the row; benefits stay visible inside each offer.
import type { Ref } from "react";
import { Heading } from "react-aria-components";
import { Avatar } from "../components/Avatar";
import { Badge } from "../components/Badge";
import { Card } from "../components/Card";
import { Link } from "../components/Link";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./PlanCardCompact.css";

export interface PlanCardCompactBenefit {
  label: string;
  /** A complete logo image, not initials on Avatar's subtle fallback plate. */
  logo: string;
}

export interface PlanCardCompactProps {
  planName: string;
  title: string;
  /**
   * Heading level of the title, so the card sits at the right depth in the page outline: `2` for a
   * list placed directly under the page's h1. Card's `headingLevel`, and the same default.
   *
   * @default 3
   */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
  href?: string;
  specs: string[];
  /** Up to three visible benefits, in priority order. */
  benefits: readonly PlanCardCompactBenefit[];
  price: string;
  tag?: string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function PlanCardCompact({ planName, title, headingLevel = 3, href, specs, benefits, price, tag,
  className, ref }: PlanCardCompactProps) {
  return (
    <Card ref={ref} className={className ? `sd-plancardcompact ${className}` : "sd-plancardcompact"}>
      <Stack gap="x-small">
        <p className="sd-plancardcompact__name sd-type-caption-medium">{planName}</p>
        {/* React Aria's Heading, as CardTitle uses: safe inside a Dialog's heading context. */}
        <Heading level={headingLevel} className="sd-plancardcompact__title sd-type-title-medium-emphasized">
          {href ? <Link href={href} variant="quiet">{title}</Link> : title}
        </Heading>
        <ul className="sd-plancardcompact__specs">
          {specs.map((spec, index) => (
            /* CONTRASTIVE: one rung below the title it describes, a spec line under its plan. */
            <li key={`${index}-${spec}`} className="sd-plancardcompact__spec sd-type-body-small">
              <Separator isDecorative orientation="vertical" className="sd-plancardcompact__rule" />
              {spec}
            </li>
          ))}
        </ul>
      </Stack>
      <Card variant="sunken" className="sd-plancardcompact__benefits">
        <Stack as="ul" gap="small" className="sd-plancardcompact__list">
          {benefits.slice(0, 3).map((benefit, index) => (
            <Stack as="li" key={`${index}-${benefit.label}`} direction="row" align="center" gap="small">
              <Avatar size="small" src={benefit.logo} alt="" />
              {/* CONTRASTIVE: one rung below the title, as the specs, so the panel reads as support. */}
              <p className="sd-plancardcompact__benefit sd-type-body-small-emphasized">{benefit.label}</p>
            </Stack>
          ))}
        </Stack>
      </Card>
      <Stack direction="row" justify="end" align="center" gap="small" wrap>
        {tag && <Badge variant="neutral">{tag}</Badge>}
        <p className="sd-plancardcompact__price sd-type-title-medium-emphasized">{price}</p>
      </Stack>
    </Card>
  );
}

/* Arrangement and the Block's own text ink; composed Components own all surfaces and shapes. */
.sd-plancardcompact {
  min-width: 0;
  width: 100%;
}
.sd-plancardcompact__name,
.sd-plancardcompact__title,
.sd-plancardcompact__price,
.sd-plancardcompact__benefit {
  margin: 0;
}
.sd-plancardcompact__name,
.sd-plancardcompact__specs {
  color: var(--sd-color-text-muted);
}
.sd-plancardcompact__price {
  color: var(--sd-color-text-brand);
}
.sd-plancardcompact__benefits {
  flex: 1;
}
.sd-plancardcompact__list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.sd-plancardcompact__benefit {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Like PlanCard: wrapping clips the leading divider instead of leaving one at a line edge. */
.sd-plancardcompact__specs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sd-space-2x-small) var(--sd-space-medium);
  margin: 0;
  padding: 0;
  overflow: hidden;
  list-style: none;
}
.sd-plancardcompact__spec {
  position: relative;
}
.sd-plancardcompact__rule {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: calc(var(--sd-space-medium) / -2);
  block-size: 0.75em;
  min-block-size: 0;
  translate: -50% -50%;
}
